'use client';

import { useId, useLayoutEffect, useRef, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

import { PersonAvatar } from './_parts/glyphs';
import { Swap } from './_parts/motion-parts';
import { actorNameOf, personOf } from './_parts/people';
import { relativeTimeOf } from './_parts/time';

type Segment = {
  text: string;
  isMention?: boolean;
};

type QuotedEvent = {
  id: string;
  actorId: string;
  at: string;
  action: string;
  taskKey: string;
  quote: Segment[];
};

const EVENTS: QuotedEvent[] = [
  {
    id: 'q1',
    actorId: 'sana',
    at: '2026-11-05T10:46:00',
    action: 'mentioned you in a comment on',
    taskKey: 'MOS-217',
    quote: [
      { text: '@Amara', isMention: true },
      {
        text: ' the quarterly report filters now keep their values when you switch between teams. The saved views still forget the date range though, so I left that part for a follow-up task. Could you check whether finance needs the range saved before Friday, or whether the follow-up can wait for the next cycle?',
      },
    ],
  },
  {
    id: 'q2',
    actorId: 'leo',
    at: '2026-11-05T09:58:00',
    action: 'replied to your comment on',
    taskKey: 'MOS-214',
    quote: [
      {
        text: 'Agreed, the totals row goes last. I will ship the column picker today and keep the totals for tomorrow morning.',
      },
    ],
  },
  {
    id: 'q3',
    actorId: 'tomas',
    at: '2026-11-04T16:12:00',
    action: 'mentioned you in a comment on',
    taskKey: 'MOS-209',
    quote: [
      { text: 'The refund copy reads well. ' },
      { text: '@Amara', isMention: true },
      {
        text: ', can the second paragraph lose the legal wording? Support says people stop reading there, and the same terms already sit behind the link at the foot of the page, so nothing is lost if we cut it.',
      },
    ],
  },
];

function QuoteText({
  segments,
  isOpen,
  textId,
  onClampChange,
}: {
  segments: Segment[];
  isOpen: boolean;
  textId: string;
  onClampChange: (isClamped: boolean) => void;
}) {
  const textRef = useRef<HTMLParagraphElement>(null);

  useLayoutEffect(() => {
    const node = textRef.current;
    if (!node) {
      return;
    }
    if (isOpen) {
      return;
    }
    const observer = new ResizeObserver(() => {
      const overflows = node.scrollHeight > node.clientHeight + 1;
      onClampChange(overflows);
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, [isOpen, onClampChange]);

  return (
    <p
      ref={textRef}
      id={textId}
      className={cn(
        'text-[13px] leading-5 [overflow-wrap:anywhere]',
        !isOpen && 'line-clamp-2'
      )}
    >
      {segments.map((segment, index) => {
        const key = `${index}-${segment.text}`;
        if (segment.isMention) {
          return (
            <span
              key={key}
              className='bg-primary/10 text-primary-ink dark:bg-primary/20 rounded-[4px] px-0.5 font-medium'
            >
              {segment.text}
            </span>
          );
        }
        return <span key={key}>{segment.text}</span>;
      })}
    </p>
  );
}

function toggleLabelOf(isOpen: boolean) {
  if (isOpen) {
    return 'Show less';
  }
  return 'Show more';
}

function QuotedEntry({ event }: { event: QuotedEvent }) {
  const [isOpen, setIsOpen] = useState(false);
  const [isClamped, setIsClamped] = useState(false);
  const textId = useId();
  const showsToggle = isClamped || isOpen;
  const label = toggleLabelOf(isOpen);

  return (
    <li className='flex gap-3 py-2.5'>
      <PersonAvatar
        person={personOf(event.actorId)}
        className='size-7 text-[10px]'
      />
      <div className='min-w-0 flex-1'>
        <div className='flex items-start justify-between gap-3'>
          <p className='text-muted-foreground min-w-0 text-[13px] leading-5'>
            <span className='text-foreground font-medium'>
              {actorNameOf(event.actorId)}
            </span>{' '}
            {event.action}{' '}
            <span className='text-foreground tabular-nums'>
              {event.taskKey}
            </span>
          </p>
          <time
            dateTime={event.at}
            className='text-muted-foreground shrink-0 pt-0.5 text-xs tabular-nums'
          >
            {relativeTimeOf(event.at)}
          </time>
        </div>
        <blockquote className='bg-foreground/[0.03] mt-1.5 rounded-lg px-3 py-2'>
          <AnimatedSize>
            <QuoteText
              segments={event.quote}
              isOpen={isOpen}
              textId={textId}
              onClampChange={setIsClamped}
            />
          </AnimatedSize>
          {showsToggle && (
            <button
              type='button'
              aria-expanded={isOpen}
              aria-controls={textId}
              onClick={() => setIsOpen((current) => !current)}
              className='text-primary-ink focus-visible:ring-ring/25 mt-1 cursor-pointer rounded-sm text-xs font-medium outline-none hover:underline focus-visible:ring-[3px]'
            >
              <AnimatedSize as='span' axis='width'>
                <Swap swapKey={label}>{label}</Swap>
              </AnimatedSize>
            </button>
          )}
        </blockquote>
      </div>
    </li>
  );
}

export default function Activity07() {
  return (
    <section aria-label='Mentions and replies' className='w-full max-w-md'>
      <h3 className='text-sm font-medium'>Mentions and replies</h3>
      <ul className='mt-1'>
        {EVENTS.map((event) => (
          <QuotedEntry key={event.id} event={event} />
        ))}
      </ul>
    </section>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import type { Person } from './people';

export type StatusId =
  'backlog' | 'todo' | 'in_progress' | 'in_review' | 'done';

export type PriorityId = 'urgent' | 'high' | 'medium' | 'low';

export const STATUS_NAME: Record<StatusId, string> = {
  backlog: 'Backlog',
  todo: 'Todo',
  in_progress: 'In progress',
  in_review: 'In review',
  done: 'Done',
};

const STATUS_COLOR: Record<StatusId, string> = {
  backlog: 'var(--muted-foreground)',
  todo: 'var(--muted-foreground)',
  in_progress: 'var(--warning)',
  in_review: 'var(--primary)',
  done: 'var(--success)',
};

export const PRIORITY_NAME: Record<PriorityId, string> = {
  urgent: 'Urgent',
  high: 'High',
  medium: 'Medium',
  low: 'Low',
};

const PIE_RADIUS = 2;

const PIE_CIRCUMFERENCE = 2 * Math.PI * PIE_RADIUS;

function StartedShape({ share }: { share: number }) {
  const filled = share * PIE_CIRCUMFERENCE;
  return (
    <>
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
      <circle
        cx='7'
        cy='7'
        r={PIE_RADIUS}
        stroke='currentColor'
        strokeWidth={PIE_RADIUS * 2}
        strokeDasharray={`${filled} ${PIE_CIRCUMFERENCE}`}
        transform='rotate(-90 7 7)'
      />
    </>
  );
}

function statusShapeOf(status: StatusId) {
  if (status === 'backlog') {
    return (
      <circle
        cx='7'
        cy='7'
        r='6'
        stroke='currentColor'
        strokeWidth='1.5'
        strokeDasharray='1.6 1.9'
      />
    );
  }
  if (status === 'todo') {
    return (
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
    );
  }
  if (status === 'in_progress') {
    return <StartedShape share={0.5} />;
  }
  if (status === 'in_review') {
    return <StartedShape share={0.75} />;
  }
  return (
    <>
      <circle cx='7' cy='7' r='7' fill='currentColor' />
      <path
        d='M4.4 7.2 6.2 9l3.4-3.8'
        stroke='var(--card)'
        strokeWidth='1.6'
        strokeLinecap='round'
        strokeLinejoin='round'
      />
    </>
  );
}

export function StatusGlyph({
  status,
  className,
}: {
  status: StatusId;
  className?: string;
}) {
  const glyphStyle = { color: STATUS_COLOR[status] } as React.CSSProperties;
  return (
    <svg
      viewBox='0 0 14 14'
      fill='none'
      aria-hidden='true'
      style={glyphStyle}
      className={cn('size-3.5 shrink-0', className)}
    >
      {statusShapeOf(status)}
    </svg>
  );
}

const BAR_HEIGHTS = [4, 7, 10];

const FILLED_BARS: Record<PriorityId, number> = {
  urgent: 3,
  high: 3,
  medium: 2,
  low: 1,
};

function barOpacityOf(index: number, filledCount: number) {
  if (index < filledCount) {
    return 0.8;
  }
  return 0.2;
}

export function PriorityGlyph({
  priority,
  className,
}: {
  priority: PriorityId;
  className?: string;
}) {
  const isUrgent = priority === 'urgent';
  const filledCount = FILLED_BARS[priority];
  return (
    <svg
      viewBox='0 0 14 14'
      aria-hidden='true'
      className={cn(
        'text-foreground size-3.5 shrink-0',
        isUrgent && 'text-destructive-ink',
        className
      )}
    >
      {BAR_HEIGHTS.map((height, index) => (
        <rect
          key={height}
          x={1.5 + index * 4.25}
          y={12 - height}
          width='2.5'
          height={height}
          rx='0.75'
          fill='currentColor'
          fillOpacity={barOpacityOf(index, filledCount)}
        />
      ))}
    </svg>
  );
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={cn('size-6 text-[10px]', className)}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
      <AvatarFallback>{person.initials}</AvatarFallback>
    </Avatar>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

export const EASE_OUT_STRONG: [number, number, number, number] = [
  0.23, 1, 0.32, 1,
];

export const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

export const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

export type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that arrive or leave a list: their height opens and closes so the rows after them slide. */
export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

/** An icon or a short label that becomes another one in place. */
export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

type RollingCountProps = {
  value: number;
  /** Writes the value, such as a duration; the digits still roll on the number. */
  format?: (value: number) => string;
  className?: string;
};

function plainNumber(value: number) {
  return String(value);
}

/** A figure the person just changed: the new digits slide in from the side of the change. */
export function RollingCount({
  value,
  format = plainNumber,
  className,
}: RollingCountProps) {
  const shouldReduceMotion = useReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {format(value)}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

